// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != c.owner());
        vm.assume(actor != address(this)); // the test contract is admin
        vm.prank(actor);
        try c.setOwner(newOwner) {
            // If it succeeds (the bug), owner changes to newOwner.
            // The property: if caller is not admin, owner must remain unchanged.
            assertTrue(c.owner() != newOwner);
        } catch {
            // Reverted as expected: owner unchanged, property holds vacuously.
            assertTrue(c.owner() != newOwner);
        }
    }
}

