// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        // Ensure nonAdmin is neither the original admin (msg.sender of setUp) nor the current owner.
        vm.assume(nonAdmin != address(this)); // setUp's msg.sender is the admin
        vm.assume(nonAdmin != c.owner());
        // Record owner before setOwner call
        address ownerBefore = c.owner();
        // Call setOwner as nonAdmin
        vm.prank(nonAdmin);
        bool ok;
        try c.setOwner(newOwner) returns (bool) { ok = true; } catch { ok = false; }
        // If the call did not revert, the owner must remain unchanged.
        // The reference requires nonAdmin != admin so the call reverts.
        // The mutant allows nonAdmin == owner to succeed, changing owner.
        assertTrue(!ok || c.owner() == ownerBefore);
    }
}

