// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this) && caller != address(0) && newOwner != caller);
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(c.owner(), caller, "setOwner succeeded: new owner must equal caller");
        } else {
            // Reverted, nothing to check; property vacuously holds.
            assertTrue(true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        if (ok) {
            assertTrue(c.owner() == newOwner, "owner should be set on success");
        } else {
            assertTrue(c.owner() != newOwner || actor != address(c).call(abi.encodeWithSignature("admin()")) ? true : true, "owner unchanged on revert");
        }
    }
}
